//! Build-time codegen, invoked from `build.zig` via `addRunArtifact`.
//!
//! Parses the task configuration JSON, validates it, computes the resource
//! priority ceilings, and emits a Zig source module containing the results
//! as comptime constants. The generated files are written into the source
//! tree (src/generated/) so they can be read and versioned like any other
//! source file; every `zig build` regenerates them, so hand edits are lost.
//! If the configuration is invalid, this program exits non-zero and the
//! build fails with the diagnostic below — no invalid configuration can
//! ever make it into a compiled binary.

const std = @import("std");
const Io = std.Io;

const rticz = @import("rticz");

pub fn main(init: std.process.Init) !void {
    const arena = init.arena.allocator();
    const io = init.io;

    const args = try init.minimal.args.toSlice(arena);
    if (args.len != 4) std.process.fatal(
        "usage: analyze_codegen CONFIG.json ANALYSIS_OUT.zig GLUE_OUT.zig",
        .{},
    );
    const cfg_path = args[1];
    const out_path = args[2];
    const glue_path = args[3];

    const parsed = rticz.parser.parseFile(io, arena, cfg_path) catch |err|
        std.process.fatal("invalid task configuration '{s}': {s}", .{ cfg_path, describeError(err) });
    const ceilings = rticz.ceiling.compute(arena, parsed.value) catch |err|
        std.process.fatal("ceiling analysis failed for '{s}': {s}", .{ cfg_path, @errorName(err) });

    // Task ids double as Zig identifiers in the generated dispatch table.
    for (parsed.value) |task| {
        if (!isValidZigIdentifier(task.task_id)) std.process.fatal(
            "task_id '{s}' is not a valid Zig identifier; the generated glue implements dispatch via `{s}` in the application root",
            .{ task.task_id, task.task_id },
        );
    }

    var out_writer: Io.Writer.Allocating = .init(arena);
    const w = &out_writer.writer;

    try w.writeAll(
        \\//! @generated by `zig build` (src/analyze_codegen.zig) — do not edit.
        \\//! Regenerated into src/generated/ on every build; commit as-is.
        \\//!
        \\//! The task configuration below was parsed, validated, and analyzed at
        \\//! build time by build.zig; the tables are comptime constants, so the
        \\//! binary answers queries without any JSON parsing or heap allocation.
        \\//! The comptime block at the bottom re-derives every ceiling from the
        \\//! task table and fails compilation if the two ever disagree.
        \\
        \\const std = @import("std");
        \\const rticz = @import("rticz");
        \\
        \\
    );

    try w.print("/// Configuration file this analysis was generated from.\npub const source_file = ", .{});
    try emitString(w, std.fs.path.basename(cfg_path));
    try w.writeAll(";\n\n");

    try w.print("/// Tasks exactly as declared in the configuration ({d} entries).\npub const tasks = [_]rticz.parser.Task{{\n", .{parsed.value.len});
    for (parsed.value) |task| {
        try w.writeAll("    .{ .task_id = ");
        try emitString(w, task.task_id);
        try w.writeAll(", .interrupt_id = ");
        try emitString(w, task.interrupt_id);
        try w.print(", .priority = {d}, .resources = &.{{", .{task.priority});
        for (task.resources, 0..) |res, j| {
            if (j != 0) try w.writeAll(", ");
            try emitString(w, res);
        }
        try w.writeAll("} },\n");
    }
    try w.writeAll("};\n\n");

    try w.print("/// Resource priority ceilings computed at build time ({d} entries).\npub const ceilings = [_]rticz.ceiling.ResourceCeiling{{\n", .{ceilings.len});
    for (ceilings) |c| {
        try w.writeAll("    .{ .name = ");
        try emitString(w, c.name);
        try w.print(", .ceiling = {d} }},\n", .{c.ceiling});
    }
    try w.writeAll("};\n\ncomptime {\n");

    // Independent re-verification: even if this codegen program were buggy,
    // the compiler itself re-checks the tables against the protocol rules.
    try w.writeAll(
        \\    // Every used resource has a ceiling entry that no accessing task exceeds.
        \\    for (tasks) |task| {
        \\        for (task.resources) |res| {
        \\            var best: ?u8 = null;
        \\            for (ceilings) |c| {
        \\                if (std.mem.eql(u8, c.name, res)) {
        \\                    best = c.ceiling;
        \\                    break;
        \\                }
        \\            }
        \\            if (best == null) @compileError("resource has no ceiling entry: " ++ res);
        \\            if (task.priority > best.?) @compileError("task priority exceeds the resource ceiling");
        \\        }
        \\    }
        \\    // Every ceiling entry is exactly the maximum over its accessing tasks.
        \\    for (ceilings) |c| {
        \\        var max: u8 = 0;
        \\        var used = false;
        \\        for (tasks) |task| for (task.resources) |res| {
        \\            if (std.mem.eql(u8, res, c.name)) {
        \\                used = true;
        \\                if (task.priority > max) max = task.priority;
        \\            }
        \\        };
        \\        if (!used) @compileError("ceiling entry for a resource no task uses: " ++ c.name);
        \\        if (max != c.ceiling) @compileError("ceiling is not the max over accessing tasks: " ++ c.name);
        \\    }
        \\
    );
    try w.writeAll("}\n");

    try writeAllToFile(io, out_path, out_writer.toArrayList().items);
    try writeAllToFile(io, glue_path, glue_source);
}

/// The RTIC-style scheduler glue. Fully generic: every configuration-specific
/// check is performed at comptime against the generated `analysis` module,
/// so the same source works for any valid task configuration.
const glue_source =
    \\//! @generated by `zig build` (src/analyze_codegen.zig) — do not edit.
    \\//! RTIC-style scheduler glue, regenerated into src/generated/ each build.
    \\//!
    \\//! Root of the `rticz` executable. At comptime this file verifies that
    \\//! the application root (src/root.zig) implements `init`, a `noreturn`
    \\//! `idle`, and an `fn() void` handler for every task declared in the
    \\//! build configuration; assembles the dispatch table; and then runs the
    \\//! RTIC boot sequence: init, then idle forever.
    \\
    \\const std = @import("std");
    \\const app = @import("app");
    \\
    \\pub const analysis = @import("analysis");
    \\
    \\/// One entry of the scheduler dispatch table.
    \\pub const Dispatch = struct {
    \\    task_id: []const u8,
    \\    interrupt_id: []const u8,
    \\    priority: u8,
    \\    handler: *const fn () void,
    \\};
    \\
    \\/// Dispatch table assembled at comptime: one entry per configured task,
    \\/// wired directly to the matching handler in the application root.
    \\pub const dispatch: [analysis.tasks.len]Dispatch = blk: {
    \\    var table: [analysis.tasks.len]Dispatch = undefined;
    \\    for (analysis.tasks, 0..) |task, i| {
    \\        table[i] = .{
    \\            .task_id = task.task_id,
    \\            .interrupt_id = task.interrupt_id,
    \\            .priority = task.priority,
    \\            .handler = &@field(app, task.task_id),
    \\        };
    \\    }
    \\    break :blk table;
    \\};
    \\
    \\comptime {
    \\    // The application root must provide the RTIC skeleton...
    \\    if (!@hasDecl(app, "init")) @compileError(
    \\        "application root is missing `pub fn init() void`",
    \\    );
    \\    if (!@hasDecl(app, "idle")) @compileError(
    \\        "application root is missing `pub fn idle() noreturn`",
    \\    );
    \\    const init_info = @typeInfo(@TypeOf(app.init)).@"fn";
    \\    if (init_info.param_types.len != 0 or init_info.return_type != void) @compileError(
    \\        "`init` must have signature `pub fn init() void`",
    \\    );
    \\    const idle_info = @typeInfo(@TypeOf(app.idle)).@"fn";
    \\    if (idle_info.param_types.len != 0 or idle_info.return_type != noreturn) @compileError(
    \\        "`idle` must have signature `pub fn idle() noreturn` — it must never return",
    \\    );
    \\    // ...and a handler for every task declared in the configuration.
    \\    for (analysis.tasks) |task| {
    \\        if (!@hasDecl(app, task.task_id)) @compileError(
    \\            "task '" ++ task.task_id ++ "' declared in " ++ analysis.source_file ++
    \\                " is not implemented in the application root (expected `pub fn " ++
    \\                task.task_id ++ "() void`)",
    \\        );
    \\        const handler_info = @typeInfo(@TypeOf(@field(app, task.task_id))).@"fn";
    \\        if (handler_info.param_types.len != 0 or handler_info.return_type != void) @compileError(
    \\            "task handler '" ++ task.task_id ++ "' must have signature `pub fn " ++
    \\                task.task_id ++ "() void`",
    \\        );
    \\    }
    \\}
    \\
    \\/// The RTIC boot sequence, reduced to its essence: initialize, then
    \\/// hand control to idle, which never returns (checked at comptime above).
    \\pub fn main(init: std.process.Init) !void {
    \\    _ = init;
    \\    app.init();
    \\    app.idle();
    \\}
    \\
    \\test "dispatch table matches the build-time analysis" {
    \\    try std.testing.expectEqual(analysis.tasks.len, dispatch.len);
    \\    for (analysis.tasks, dispatch) |task, entry| {
    \\        try std.testing.expectEqualStrings(task.task_id, entry.task_id);
    \\        try std.testing.expectEqualStrings(task.interrupt_id, entry.interrupt_id);
    \\        try std.testing.expectEqual(task.priority, entry.priority);
    \\    }
    \\}
    \\
;

/// Writes `bytes` to `path`, creating the parent directory when missing.
/// Relative paths resolve against the process working directory, which for
/// a build-system run step is the package root.
fn writeAllToFile(io: Io, path: []const u8, bytes: []const u8) !void {
    const dirname = std.fs.path.dirname(path) orelse ".";
    var file = if (std.fs.path.isAbsolute(path)) blk: {
        var parent = if (dirname.len == 0)
            std.Io.Dir.cwd()
        else if (std.fs.path.isAbsolute(dirname))
            try std.Io.Dir.openDirAbsolute(io, dirname, .{})
        else
            try std.Io.Dir.cwd().openDir(io, dirname, .{});
        defer parent.close(io);
        break :blk try parent.createFile(io, std.fs.path.basename(path), .{});
    } else blk: {
        const cwd = std.Io.Dir.cwd();
        try cwd.createDirPath(io, dirname);
        break :blk try cwd.createFile(io, path, .{});
    };
    defer file.close(io);
    var buf: [8 * 1024]u8 = undefined;
    var file_writer = Io.File.Writer.init(file, io, &buf);
    try file_writer.interface.writeAll(bytes);
    try file_writer.interface.flush();
}

fn isValidZigIdentifier(s: []const u8) bool {
    if (s.len == 0) return false;
    if (!std.ascii.isAlphabetic(s[0]) and s[0] != '_') return false;
    for (s[1..]) |c| {
        if (!std.ascii.isAlphanumeric(c) and c != '_') return false;
    }
    // A name that is also a Zig keyword would break the generated code.
    return !std.zig.Token.keywords.has(s);
}

/// Emit `s` as a Zig string literal.
fn emitString(w: anytype, s: []const u8) !void {
    try w.writeByte('"');
    for (s) |ch| switch (ch) {
        '"' => try w.writeAll("\\\""),
        '\\' => try w.writeAll("\\\\"),
        '\n' => try w.writeAll("\\n"),
        '\r' => try w.writeAll("\\r"),
        '\t' => try w.writeAll("\\t"),
        else => try w.writeByte(ch),
    };
    try w.writeByte('"');
}

fn describeError(err: anyerror) []const u8 {
    return switch (err) {
        error.FileNotFound => "file not found",
        error.AccessDenied, error.PermissionDenied => "permission denied",
        error.IsDir => "expected a file but found a directory",
        error.StreamTooLong => "file too large (limit 1 MiB)",
        error.SyntaxError, error.UnexpectedToken, error.UnexpectedEndOfInput => "invalid JSON syntax",
        error.MissingField => "missing required field (task_id, interrupt_id, priority, resources)",
        error.UnknownField => "unknown field in task object",
        error.DuplicateField => "duplicate field in task object",
        error.Overflow => "priority out of range (must fit a u8, 0–255)",
        error.InvalidNumber => "invalid number literal",
        error.DuplicateTaskId => "duplicate task_id",
        error.DuplicateResource => "duplicate resource within a task",
        error.EmptyTaskId => "empty task_id",
        error.EmptyInterruptId => "empty interrupt_id",
        else => @errorName(err),
    };
}
